theorem pairScale_AM10D {k : ℕ} {p z : BiPoly × BiPoly}
 (hz : PairScaleM10D k p z) :
 PairScaleM10D (k+1) (rawRowAM10D p) (atomicAMEA423 z)

theorem pairScale_CM10D {k : ℕ} {p z : BiPoly × BiPoly}
 (hz : PairScaleM10D k p z) :
 PairScaleM10D k (rawRowCM10D p) (atomicCMEA423 z)

theorem pairScale_highM10D {k : ℕ} {p z : BiPoly × BiPoly}
 (hz : PairScaleM10D k p z) (j : ℕ) (hj : k≤2*j) :
 z.2.coeff j=(X+1)^(2*j-k)*p.2.coeff j

theorem pairScale_lowM10D {k : ℕ} {p z : BiPoly × BiPoly}
 (hz : PairScaleM10D k p z) (j : ℕ) (hj : 2*j≤k) :
 p.2.coeff j=(X+1)^(k-2*j)*z.2.coeff j

theorem swap_rawAtomicM10D (z : BiPoly × BiPoly) (r : Bool) :
 swapPairM10D (rawAtomicM10D z r)=
 if r then rawRowCM10D (swapPairM10D z) else rawRowAM10D (swapPairM10D z)

theorem swap_raw_word_stepM10D (w : List Bool) (r : Bool) :
 swapPairM10D (rawPairM10D (expand80 (w++[r])))=
 if r then rawRowCM10D (rawRowAM10D (swapPairM10D (rawPairM10D (expand80 w))))
 else rawRowAM10D (swapPairM10D (rawPairM10D (expand80 w)))
